    {
      "file": "corpus/giron-d/sent/410.eml",
      "quote": "We did this for the first time today and noted numerous curves in",
      "note": "The manual process misses curves often enough that RAR added a weekly check by hand, which a nightly automated report would replace."
    },
    {
      "file": "corpus/giron-d/sent/569.eml",
      "quote": "Done.",
      "note": "The TAGG step is a separate email round trip with Jeremy Wong for each batch of curves."
    }
  ],
  "ongoing": true,
  "stated_rate": {
    "count": 1,
    "per": "week",
    "file": "corpus/giron-d/sent/410.eml",
    "quote": "on a weekly basis new curves set up in ERMS are reviewed"
